package ca.uqac.inf865.truestay.ui.theme
import androidx.compose.ui.text.font.Font import androidx.compose.ui.text.font.FontFamily import androidx.compose.ui.text.font.FontWeight import ca.uqac.inf865.truestay.R
/** * Defines the Montserrat font family. * * Make sure you have the following files in `app/src/main/res/font`: * - `montserrat_regular.ttf` * - `montserrat_semibold.ttf` * - `montserrat_bold.ttf` */ val Montserrat = FontFamily( Font(R.font.montserrat_regular, FontWeight.Normal), Font(R.font.montserrat_semibold, FontWeight.SemiBold), Font(R.font.montserrat_bold, FontWeight.Bold) )

package ca.uqac.inf865.truestay.ui.theme
import androidx.compose.ui.text.font.Font import androidx.compose.ui.text.font.FontFamily import androidx.compose.ui.text.font.FontWeight import ca.uqac.inf865.truestay.R
/** * Defines the Montserrat font family. * * Make sure you have the following files in `app/src/main/res/font`: * - `montserrat_regular.ttf` * - `montserrat_semibold.ttf` * - `montserrat_bold.ttf` */ val Montserrat = FontFamily( Font(R.font.montserrat_regular, FontWeight.Normal), Font(R.font.montserrat_semibold, FontWeight.SemiBold), Font(R.font.montserrat_bold, FontWeight.Bold) )

@echo off
echo ====================================
echo Configuration du Pare-feu Windows
echo pour les emulateurs Firebase
echo ====================================
echo.
echo Ce script doit etre execute en tant qu'administrateur!
echo.
echo Appuyez sur une touche pour continuer ou fermez cette fenetre pour annuler...
pause > nul

echo.
echo Creation des regles de pare-feu...
echo.

netsh advfirewall firewall add rule name="Firebase Auth Emulator" dir=in action=allow protocol=TCP localport=9099
netsh advfirewall firewall add rule name="Firebase Firestore Emulator" dir=in action=allow protocol=TCP localport=8080
netsh advfirewall firewall add rule name="Firebase Storage Emulator" dir=in action=allow protocol=TCP localport=9199
netsh advfirewall firewall add rule name="Firebase Functions Emulator" dir=in action=allow protocol=TCP localport=5001
netsh advfirewall firewall add rule name="Firebase Emulator UI" dir=in action=allow protocol=TCP localport=4000

echo.
echo ====================================
echo Configuration terminee!
echo ====================================
echo.
echo Les ports suivants sont maintenant ouverts:
echo - 9099 (Auth)
echo - 8080 (Firestore)
echo - 9199 (Storage)
echo - 5001 (Functions)
echo - 4000 (Emulator UI)
echo.
pause
